import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"On-demand servers","description":"","frontmatter":{},"headers":[],"relativePath":"guide/on-demand.md","filePath":"guide/on-demand.md","lastUpdated":1787179449000}`),a={name:`guide/on-demand.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="on-demand-servers" tabindex="-1">On-demand servers <a class="header-anchor" href="#on-demand-servers" aria-label="Permalink to “On-demand servers”">​</a></h1><p>Local servers — stdio children and <a href="/guide/sandboxing">Docker sandboxes</a> — do not have to run around the clock. By default the hub starts them when they are used and puts them back to sleep after 60 minutes of inactivity, which is what makes a dozen servers affordable on a Raspberry Pi: memory is held only by the servers actually in use.</p><p>Remote and socket servers are unaffected — the hub does not manage the lifetime of a process it did not start.</p><h2 id="the-lifecycle" tabindex="-1">The lifecycle <a class="header-anchor" href="#the-lifecycle" aria-label="Permalink to “The lifecycle”">​</a></h2><div class="language-"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span>boot ──(cached snapshot)──► sleeping ──(tool call / wake)──► up</span></span>
<span class="line"><span>                                ▲                            │</span></span>
<span class="line"><span>                                └────── 60 min idle ─────────┘</span></span></code></pre></div><ul><li><strong>Boot.</strong> A server whose snapshot is in the <a href="#the-tool-cache">tool cache</a> boots straight into <code>sleeping</code> and costs nothing. Without a snapshot (first run, changed config) it warm-starts once to fill the cache and idles out afterwards.</li><li><strong>Use.</strong> The first <code>tools/call</code> (or resources/prompts request) wakes the server and <strong>blocks until it is up</strong> — transparent to the client, the first call is just slower. Concurrent requests share the one start; after 120 seconds without a successful start the request fails with the server&#39;s last error.</li><li><strong>Idle.</strong> Every forwarded request resets the server&#39;s idle clock. Once it has been quiet for the idle timeout, the hub tears it down: the stdio child exits, a sandbox container is removed. The hub&#39;s internal keepalive ping does not count as activity — and a sleeping server is not pinged at all.</li></ul><h2 id="what-wakes-a-server-and-what-does-not" tabindex="-1">What wakes a server (and what does not) <a class="header-anchor" href="#what-wakes-a-server-and-what-does-not" aria-label="Permalink to “What wakes a server (and what does not)”">​</a></h2><p>A client with several hub paths configured enumerates all of them on session start. If that woke the fleet, on-demand would save nothing — so the handshake is answered from the snapshot:</p><table tabindex="0"><thead><tr><th>Request</th><th>Effect on a sleeping server</th></tr></thead><tbody><tr><td><code>initialize</code>, <code>tools/list</code> on <code>/&lt;name&gt;/mcp</code></td><td>answered from the snapshot; stays asleep</td></tr><tr><td><code>tools/call</code>, resources, prompts on <code>/&lt;name&gt;/mcp</code></td><td>wakes, blocks until up, then forwards</td></tr><tr><td><code>/hub</code> <code>list_tools</code>, <code>get_tool_schema</code></td><td>answered from the snapshot <strong>and</strong> pre-warms the server in the background — asking for schemas is the strongest hint a call follows</td></tr><tr><td><code>/hub</code> <code>call_tool</code></td><td>wakes and blocks, like a direct call</td></tr><tr><td><code>/hub</code> <code>list_servers</code>, <code>/health</code></td><td>read state only; never wake anything</td></tr></tbody></table><p>The cached <code>tools/list</code> reflects the server as it last ran. After a wake the live list is forwarded again and the snapshot is refreshed.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h2><p>On-demand is the default for every stdio and docker server. Two per-server fields and one environment variable tune it:</p><div class="language-json"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">{</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: {</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;paperless&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;paperless-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">] },</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;search&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:     { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;search-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">], </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;idleMinutes&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">15</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> },</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">    &quot;workhorse&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:  { </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;command&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;npx&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;args&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: [</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;-y&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">, </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;busy-mcp&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">], </span><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">&quot;keepAlive&quot;</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0550AE;--shiki-dark:#79C0FF;">true</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;"> }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">  }</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">}</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Field</th><th>Meaning</th></tr></thead><tbody><tr><td><code>keepAlive: true</code></td><td>This server always runs, exactly like pre-0.9 behaviour. For the servers you use constantly, or whose cold start you never want to pay.</td></tr><tr><td><code>idleMinutes</code></td><td>Per-server idle timeout, overriding the global default. Mutually exclusive with <code>keepAlive</code>.</td></tr></tbody></table><div class="language-yaml"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">environment</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">:</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  IDLE_TIMEOUT_MINUTES</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;60&quot;</span><span style="--shiki-light:#6E7781;--shiki-dark:#8B949E;">   # global default; 0 disables on-demand entirely</span></span>
<span class="line"><span style="--shiki-light:#116329;--shiki-dark:#7EE787;">  TOOL_CACHE_PATH</span><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">: </span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&quot;/data/tool-cache.json&quot;</span></span></code></pre></div><p><code>IDLE_TIMEOUT_MINUTES: &quot;0&quot;</code> restores the previous behaviour wholesale: every server starts at boot and is restarted for as long as it is configured.</p><p>Like <code>hub</code>, both fields are mcp-hub extensions that Claude Code ignores, so the file remains a valid Claude Code config. Setting them on a remote or socket server is a config error.</p><h2 id="the-tool-cache" tabindex="-1">The tool cache <a class="header-anchor" href="#the-tool-cache" aria-label="Permalink to “The tool cache”">​</a></h2><p><code>/data/tool-cache.json</code> holds one snapshot per on-demand server: its identity, capabilities and tool list, keyed to a <strong>sha256 hash</strong> of the server&#39;s expanded config — the hash invalidates the entry when the config (or a referenced <code>\${VAR}</code>) changes without writing any secret to disk. The snapshot is written after every successful start and tool-list refresh.</p><p>The default lives under <code>DATA_PATH</code>, which a normal deployment already persists. If the path is not writable the hub logs a warning and falls back to warm-starting every on-demand server at boot — everything still works, boots are just as heavy as before 0.9.</p><h2 id="manual-control" tabindex="-1">Manual control <a class="header-anchor" href="#manual-control" aria-label="Permalink to “Manual control”">​</a></h2><p>Two <a href="/reference/hub-tools">/hub meta-tools</a> steer the lifecycle directly: <code>wake_server</code> starts a server ahead of time so a workflow&#39;s first real call is fast, <code>sleep_server</code> frees its resources immediately instead of waiting out the idle timeout. Both also accept <a href="/guide/configuration#hiding-a-server-from-hub"><code>&quot;hub&quot;: false</code></a> servers — hiding a server&#39;s tools from the aggregate does not take away the hub&#39;s responsibility for its lifecycle. <code>list_servers</code> and <a href="/reference/endpoints#status"><code>/health</code></a> both report <code>sleeping</code> as a distinct state — and <code>/health</code> counts it as healthy, because a sleeping server is exactly what this feature is for.</p><h2 id="crashes" tabindex="-1">Crashes <a class="header-anchor" href="#crashes" aria-label="Permalink to “Crashes”">​</a></h2><p>While a server is being used, a crash is handled as always: restart with exponential backoff. But a server that keeps failing <strong>without anyone asking for it</strong> stops being restarted after five attempts — it goes back to <code>sleeping</code> with its <code>lastError</code> kept visible in <code>list_servers</code> and <code>/health</code>, and the next tool call simply tries a fresh start. A broken npm package cannot occupy the machine in an endless restart loop overnight.</p><h2 id="what-it-costs" tabindex="-1">What it costs <a class="header-anchor" href="#what-it-costs" aria-label="Permalink to “What it costs”">​</a></h2><p>The first call to a sleeping server pays its cold start: a few seconds for a pinned npm package, longer for <code>npx</code> downloads on a slow disk or a sandbox image with a slow entrypoint. If a particular server&#39;s cold start is annoying, <code>keepAlive: true</code> on that one server buys back the old behaviour exactly — sizing the trade per server is the point of the flag.</p>`,26)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};